import { test, expect } from '@playwright/test';

test.describe('Form Validation - Required Field Highlighting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should highlight required fields when submitting an empty form', async ({ page }) => {
    // Intercept the form submission API
    await page.route('**/api/form-submit', (route) => {
      route.abort('API call aborted');
    });

    // Get the form by role
    const form = page.getByRole('form');
    await expect(form).toBeVisible();

    // Get the name input by label
    const nameInput = page.getByLabel('Name');
    await expect(nameInput).toBeVisible();

    // Get the email input by label
    const emailInput = page.getByLabel('Email');
    await expect(emailInput).toBeVisible();

    // Get the submit button by role
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();

    // Fill the name field
    await nameInput.fill('John Doe');

    // Fill the email field
    await emailInput.fill('john@example.com');

    // Click the submit button
    await submitButton.click();

    // Verify the form is submitted
    await expect(page).toHaveURL(/form-submitted/);

    // Verify the success message is displayed
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Verify the required fields are highlighted
    const nameError = page.getByText('Name is required');
    await expect(nameError).toBeVisible();

    const emailError = page.getByText('Email is required');
    await expect(emailError).toBeVisible();

    // Verify the form is reset after submission
    await page.waitForLoadState('networkidle');
    await expect(nameInput).toBeEmpty();
    await expect(emailInput).toBeEmpty();
  });

  test('should not highlight required fields when all fields are filled', async ({ page }) => {
    // Intercept the form submission API
    await page.route('**/api/form-submit', (route) => {
      route.abort('API call aborted');
    });

    // Get the form by role
    const form = page.getByRole('form');
    await expect(form).toBeVisible();

    // Get the name input by label
    const nameInput = page.getByLabel('Name');
    await expect(nameInput).toBeVisible();

    // Get the email input by label
    const emailInput = page.getByLabel('Email');
    await expect(emailInput).toBeVisible();

    // Get the submit button by role
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();

    // Fill the name field
    await nameInput.fill('Jane Smith');

    // Fill the email field
    await emailInput.fill('jane@example.com');

    // Click the submit button
    await submitButton.click();

    // Verify the form is submitted
    await expect(page).toHaveURL(/form-submitted/);

    // Verify the success message is displayed
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Verify the required fields are not highlighted
    const nameError = page.getByText('Name is required');
    await expect(nameError).not.toBeVisible();

    const emailError = page.getByText('Email is required');
    await expect(emailError).not.toBeVisible();

    // Verify the form is reset after submission
    await page.waitForLoadState('networkidle');
    await expect(nameInput).toHaveValue('Jane Smith');
    await expect(emailInput).toHaveValue('jane@example.com');
  });
});
